#!/usr/bin/env python3
from pathlib import Path
import json,html
P=Path(__file__).resolve().parents[1];D=P/'data/national-directory'
c=json.loads((D/'coverage-report.json').read_text());s=json.loads((D/'sources.json').read_text())['sources'];a=json.loads((D/'cleaning-audit.json').read_text());h=lambda x:html.escape(str(x or ''))
rows=[];md=[]
for p in c['provinces']:
 v=p['levels'];m=v['中职'];state='gap' if m['status']=='uncovered' else 'partial' if m['status'] in ('partial','dynamic','historical_scoped') else 'ok'
 rows.append(f'<tr data-name="{h(p["province"])}" data-state="{state}"><td><strong>{h(p["province"])}</strong></td><td>{v["职教本科"]["count"]}</td><td>{v["高职"]["count"]}</td><td><b>{m["count"]}</b></td><td><span class="tag {state}">{h(m["statusLabel"])}</span><p>{h(m["note"])}</p></td></tr>')
 md.append(f'|{p["province"]}|{v["职教本科"]["count"]}|{v["高职"]["count"]}|{m["count"]}|{m["statusLabel"]}：{m["note"]}|')
sourceCards=[]
for x in s:
 sourceCards.append(f'<details><summary>{h(x["id"])} · {h(x["title"])}</summary><p>{h(x["publisher"])} · 数据年度：{h(x.get("dataYear") or "动态/未注明")} · 发布：{h(x.get("publishedOn") or "未注明")}</p><p>{h(x["verificationScope"])}</p><p>原始提取 {x["extractedRowsBeforeCrossSourceMerge"]} 条 · 对应保留 {x["retainedRecordsReferencingSource"]} 条</p><p><a href="{h(x["pageUrl"])}" target="_blank" rel="noopener">来源网页</a> · <a href="{h(x["localFile"].removeprefix("data/national-directory/"))}" target="_blank">原件或正文证据</a></p><code>SHA-256 {x["sha256"]}</code></details>')
content='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>全国职业院校逐校数据覆盖核验报告 · V72.18</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f7fc;color:#233d64;font:15px/1.8 system-ui,-apple-system,"Microsoft YaHei",sans-serif}main{max-width:1180px;margin:auto;padding:36px 24px}header{background:#183c7d;color:white;padding:32px;border-radius:20px}header small{letter-spacing:2px;color:#a8c7ff}h1{font-size:28px;margin:10px 0}h2{font-size:21px;margin:28px 0 13px}p{margin:7px 0}.lead{color:#d9e6fb}section{background:white;border:1px solid #dfe7f4;border-radius:16px;padding:22px;margin-top:20px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:20px}.card{background:white;padding:20px;border:1px solid #dfe7f4;border-radius:14px}.card b{font-size:30px;display:block;color:#2353a7}.card small{color:#71829a}.notice{border-left:4px solid #d9932e;background:#fff7e8;padding:16px 18px;margin:18px 0;color:#835a25}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:15px 0}input,select{padding:10px;border:1px solid #ccd8ed;border-radius:8px;font:inherit}input{flex:1;min-width:210px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}thead{background:#edf3fd;color:#355b94}th,td{padding:12px 14px;text-align:left;border-bottom:1px solid #e5edf8;vertical-align:top}td:first-child{white-space:nowrap}td p{font-size:12px;color:#6b7f9b;line-height:1.8;min-width:270px}.tag{font-size:12px;padding:4px 8px;border-radius:6px}.ok{background:#e9f6ef;color:#2b7c55}.partial{background:#fff2d9;color:#97641b}.gap{background:#fceceb;color:#a54c46}a{color:#2d5fb2}details{border-bottom:1px solid #e4ebf5;padding:14px 0}summary{cursor:pointer;font-weight:600}details p{font-size:13px;color:#667c9c}code{word-break:break-all;font-size:11px;color:#7b8ba3}li{margin:6px 0}footer{font-size:12px;color:#7e8fa8;padding:20px 0}@media(max-width:700px){main{padding:18px 12px}header{padding:24px}h1{font-size:23px}.cards{grid-template-columns:1fr 1fr}.card{padding:15px}section{padding:16px}}@media print{body{background:white}.controls{display:none}main{max-width:none;padding:0}header{color:#183c7d;background:white;border:1px solid #dfe7f4}.lead{color:#456}section{break-inside:avoid}details{break-inside:avoid}}
</style><main><header><small>MVERI / VERIFIED SCHOOL DIRECTORY</small><h1>全国职业院校逐校数据<br>来源与覆盖核验报告</h1><p class="lead">V72.18 · 核验日期 2026-11-02 · 中国内地31省区市</p><p class="lead">全国中职尚未全量完成；全部记录可追溯至具体来源及原文行。</p></header>'''
content+=f'<div class="cards"><div class="card">职教本科<b>124</b><small>2026教育部名单分类核验</small></div><div class="card">高职<b>1,540</b><small>教育部专科逐校名单</small></div><div class="card">中职办学记录<b>{c["byLevel"]["中职"]:,}</b><small>含明确标注的附设单位</small></div><div class="card">中职有记录省份<b>{c["secondaryProvincePresence"]["covered"]} / 31</b><small>有记录省份比例，不是学校覆盖率</small></div></div>'
content+=f'<div class="notice"><strong>交付边界：</strong>{h(c["summary"])}<br><strong>中职全国学校覆盖率：</strong>不计算。{h(c["denominatorExplanation"])}</div><section><h2>未覆盖的中职省份</h2><p>{h("、".join(c["uncoveredSecondaryProvinces"]))}</p><p>“0条”只表示本次没有已核验逐校记录，不表示该省没有中职学校。具体障碍逐省列在下表。高职及职教本科的省份数据独立核验，不受中职缺失影响。</p></section>'
content+='<section><h2>31省区市覆盖明细</h2><p>“来源提取完整”仅针对该来源的年度、层次和办学范围。它不是当前全省全部学校的担保。</p><div class="controls"><input id="q" aria-label="搜索省份" placeholder="搜索省份"><select id="state" aria-label="过滤覆盖状态"><option value="">全部省份</option><option value="gap">中职未覆盖</option><option value="partial">中职部分或年度待核</option><option value="ok">省级或限定来源已提取</option></select></div><div class="scroll"><table><thead><tr><th>省份</th><th>职教本科</th><th>高职</th><th>中职记录</th><th>中职核验范围与限制</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div></section>'
content+=f'<section><h2>清洗与质量处理</h2><ul><li>原始输入 {a["inputRows"]:,} 条，跨行/校区规范合并后保留 {a["outputRecords"]:,} 条；已合并的专业重复在源解析阶段处理，并保留原行定位。</li><li>职业本科按教育部原表“本科”层次和《高等学校命名暂行办法》第四条规定的职业大学/职业技术大学名称核验；未将全部普通本科混入。</li><li>来源内的技工名单单独排除；有教育部门中职牌照的双挂牌单位保留原文，不把同校多挂牌拆成多所学校。</li><li>同一高校及其中职办学单位分层关联，不按名称全局删除；甘肃会宁同校两校区归并，原校区名称及定位保留。</li><li>贵州同校机构码连续递增、地址多值等异常全部保留在 originalCodes / originalAddresses 中，冲突主字段留空；广东“新设”原码不补造。</li><li>账号、入驻授权、区域归属与席位不由名录自动生成；原业务记录继续保留，未核验业务记录不计入官方名录。</li></ul><p><a href="cleaning-audit.json">完整清洗审计 JSON</a> · <a href="sources.json">来源清单 JSON</a> · <a href="schools.json">全国逐校数据 JSON</a></p></section>'
content+='<section><h2>来源逐项记录（'+str(len(s))+'项）</h2><p>原件包含云端浏览器取得的XLS/XLSX/PDF/DOCX；无附件或附件未取得的来源保存正文表格证据，并如实标注获取方式。</p>'+''.join(sourceCards)+'</section><footer>现代职业教育公共服务平台 · V72.18。学校列名及历史性质不等同实时招生资格；附设单位不等同新增独立法人院校。</footer></main><script>const q=document.querySelector("#q"),s=document.querySelector("#state");function filter(){document.querySelectorAll("tbody tr").forEach(r=>{r.hidden=!(r.dataset.name.includes(q.value.trim())&&(!s.value||r.dataset.state===s.value))})}q.addEventListener("input",filter);s.addEventListener("change",filter);</script></html>'
(D/'COVERAGE_REPORT.html').write_text(content,encoding='utf-8')
mdhead=f'# 全国职业院校逐校数据覆盖核验报告 V72.18\n\n核验日期：2026-11-02。全国中职尚未全量完成。\n\n{c["summary"]}\n\n不计算全国中职学校覆盖率：{c["denominatorExplanation"]}\n\n中职未覆盖：{"、".join(c["uncoveredSecondaryProvinces"])}。\n\n|省份|职教本科|高职|中职记录|中职范围与限制|\n|---|---:|---:|---:|---|\n'
(D/'COVERAGE_REPORT.md').write_text(mdhead+'\n'.join(md)+'\n\n详细来源及异常请查看 sources.json、cleaning-audit.json 与原始附件目录 raw/。\n',encoding='utf-8')
print('coverage report generated')
